mapper.select:
SELECT
-- 级联表的字段 ,jiaoshi.jiaoshi_uuid_number as jiaoshiUuidNumber ,jiaoshi.jiaoshi_name as jiaoshiName ,jiaoshi.jiaoshi_phone as jiaoshiPhone ,jiaoshi.jiaoshi_photo as jiaoshiPhoto
FROM mingpian_history h left JOIN jiaoshi jiaoshi ON h.jiaoshi_id = jiaoshi.id
and h.mingpian_id = #{params.mingpianId}
and h.jiaoshi_id = #{params.jiaoshiId}
and h.shangxia_types = #{params.shangxiaTypes}
order by h.version_number desc
